export function getLocalizedTreatmentContent(slug: string, language?: string): LocalizedTreatmentContent | null {
  const locale = language?.toLowerCase().startsWith("en") ? "en" : "tr";

  if (locale === "tr") {
    return null;
  }

  return TREATMENTS_TRANSLATIONS[locale]?.[slug] ?? null;
}

export function getLocalizedTreatmentCard<T extends { slug: string; title: string; category?: string; description?: string[] }>(
  item: T,
  language?: string
): T {
  const localized = getLocalizedTreatmentContent(item.slug, language);

  if (!localized) {
    return item;
  }

  return {
    ...item,
    title: localized.title,
    category: localized.category,
    description: localized.desc,
  };
}

export function getLocalizedTreatmentDetail<
  T extends {
    slug: string;
    title: string;
    category?: string;
    stats?: TreatmentStat[];
    description?: string[];
    symptoms?: string[];
    treatments?: TreatmentMethod[];
    faq?: TreatmentFaq[];
  }
>(item: T, language?: string): T {
  const localized = getLocalizedTreatmentContent(item.slug, language);

  if (!localized) {
    return item;
  }

  return {
    ...item,
    title: localized.title,
    category: localized.category,
    stats: localized.stats,
    description: localized.desc,
    symptoms: localized.symptoms,
    treatments: localized.treatment,
    faq: localized.faq,
  };
}